Theorem visit_null_root_ok : forall (LBo : list (Z * Z)) (FF LK : list fframe) (cr : credit) (A : list (Z * Z)) (sp r V S2 kx bx : Z) (g : eghost),
  g_es g = [] ->
  PMSA.cps_asan L ar HI PMESA.PC_VISIT_NULL_xboth r sp (PMESA.VIS_SCRA 12800) (LBo ++ g_lbv g) FF LK cr A PMESA.VIS_D
    (fun R M => PMSA.a0 R V /\ True /\ sp mod 32 = 0 /\ PMSA.stksh ar M sp (PMESA.VIS_SCRA 12800) /\ PMESA.enc_invA L IC EC M V S2 g /\ ev_guard (g_es g) EvNull /\
                PMESA.eroomA CL g EvNull /\ PMLA.img_ro IC M /\ PMESA.lits_ok L IC M /\ PMESA.ecreditA L CL cr g kx bx /\
                PMSA.fobj M FF V ENC_SIZE /\ PMSA.fobj M FF S2 24 /\ PMLA.apart V ENC_SIZE S2 24)
    (fun R M R' M' LB' cr' LBk W => exists (g' : eghost) (pay : Z),
        PMSA.a0 R' 1 /\ PMESA.enc_invA L IC EC M' V S2 g' /\ g_es g' = estep (g_es g) EvNull /\ pay_ok EvNull pay /\ g_len g' = g_len g + ev_ind (g_es g) EvNull + pay /\
        PMESA.lits_ok L IC M' /\ LB' = LBo ++ g_lbv g' /\ LBk = LBo /\ W = PMESA.W_encA IC V S2 /\ PMESA.ecreditA L CL cr' g' kx bx).
